mapper.select:
SELECT COUNT(*)
FROM b_wecom_chat_message m
WHERE (m.chat_id IS NULL OR m.chat_id = '')
  AND m.send_time_epoch_millis  >=  #{startTime}
  AND m.send_time_epoch_millis  <  #{endTime}
  AND EXISTS (
      SELECT 1
      FROM b_wecom_chat_message_participant employee_participant
      WHERE employee_participant.msg_id = m.msg_id
        AND employee_participant.participant_id = #{employeeUserId}
  )
  AND EXISTS (
      SELECT 1
      FROM b_wecom_chat_message_participant customer_participant
      WHERE customer_participant.msg_id = m.msg_id
        AND customer_participant.participant_id = #{externalUserId}
  )

SELECT COUNT(*)
FROM b_wecom_chat_message m
INNER JOIN b_wecom_chat_participant employee_participant
    ON employee_participant.chat_id = m.chat_id
   AND employee_participant.participant_id = #{employeeUserId}
INNER JOIN b_wecom_chat_participant customer_participant
    ON customer_participant.chat_id = m.chat_id
   AND customer_participant.participant_id = #{externalUserId}
WHERE m.chat_id IS NOT NULL
  AND m.chat_id != ''
  AND m.send_time_epoch_millis  >=  #{startTime}
  AND m.send_time_epoch_millis  <  #{endTime}

SELECT result_rows.* FROM ( SELECT m.id, m.gmt_create, m.gmt_modify, m.msg_id, m.send_time_epoch_millis, m.sender_json, m.receiver_json, m.chat_id, m.msg_type, m.secret_key, 'DIRECT' AS conversation_type FROM b_wecom_chat_message m WHERE (m.chat_id IS NULL OR m.chat_id = '') AND m.send_time_epoch_millis >= #{startTime} AND m.send_time_epoch_millis < #{endTime} AND EXISTS ( SELECT 1 FROM b_wecom_chat_message_participant employee_participant WHERE employee_participant.msg_id = m.msg_id AND employee_participant.participant_id = #{employeeUserId} ) AND EXISTS ( SELECT 1 FROM b_wecom_chat_message_participant customer_participant WHERE customer_participant.msg_id = m.msg_id AND customer_participant.participant_id = #{externalUserId} )
UNION ALL
SELECT m.id, m.gmt_create, m.gmt_modify, m.msg_id, m.send_time_epoch_millis, m.sender_json, m.receiver_json, m.chat_id, m.msg_type, m.secret_key, 'GROUP' AS conversation_type FROM b_wecom_chat_message m INNER JOIN b_wecom_chat_participant employee_participant ON employee_participant.chat_id = m.chat_id AND employee_participant.participant_id = #{employeeUserId} INNER JOIN b_wecom_chat_participant customer_participant ON customer_participant.chat_id = m.chat_id AND customer_participant.participant_id = #{externalUserId} WHERE m.chat_id IS NOT NULL AND m.chat_id != '' AND m.send_time_epoch_millis >= #{startTime} AND m.send_time_epoch_millis < #{endTime} ) result_rows ORDER BY result_rows.send_time_epoch_millis ASC, result_rows.id ASC LIMIT #{offset}, #{pageSize}
